(()=>{'use strict';let history,experiment;const E=id=>document.getElementById(id);const date=t=>new Date(t).toLocaleDateString('en-GB',{timeZone:'Europe/London',day:'2-digit',month:'short'});const ms=r=>Date.parse(r.dateTime);const valid=rows=>rows.filter(r=>Number.isFinite(r.value)&&Number.isFinite(ms(r))).sort((a,b)=>ms(a)-ms(b));
function lineChart(series,start,end,label){const W=940,H=240,left=65,right=915,top=35,bottom=195;let values=series.flatMap(s=>s.points.map(p=>p.v));if(!values.length)return '<p>No aligned observations in this window.</p>';let min=Math.min(...values),max=Math.max(...values);let pad=Math.max(.01,(max-min)*.1);min-=pad;max+=pad;const x=t=>left+(t-start)/(end-start)*(right-left),y=v=>bottom-(v-min)/(max-min)*(bottom-top);let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${label}"><text x="65" y="18" fill="#496a61" font-size="13">${label}</text>`;for(let i=0;i<4;i++){const v=min+(max-min)*i/3;svg+=`<path d="M65 ${y(v)}H915" stroke="#e0e6dc"/><text x="55" y="${y(v)+4}" text-anchor="end" font-size="12" fill="#5b706b">${v.toFixed(2)}</text>`;}for(const s of series){let path='';s.points.forEach((p,i)=>{path+=(i===0||p.t-s.points[i-1].t>(s.gap||1800000)?'M':'L')+x(p.t)+','+y(p.v)+' ';});svg+=`<path d="${path}" stroke="${s.color}" stroke-width="2.5" fill="none"/>`;}for(let i=0;i<4;i++){const t=start+(end-start)*i/3;svg+=`<text x="${x(t)}" y="225" text-anchor="${i===0?'start':i===3?'end':'middle'}" font-size="12" fill="#5b706b">${date(t)}</text>`;}return svg+'</svg>';}
function renderHistory(){const series=history.series,dig=valid(series.diglis.readings),end=ms(dig.at(-1)),start=end-Number(E('history-days').value)*86400000;const plotted=['diglis','bewdley'].map((key,i)=>{const rows=valid(series[key].readings).filter(r=>ms(r)>=start&&ms(r)<=end);return {color:i?'#b87e3d':'#27756a',points:rows.map(r=>({t:ms(r),v:r.value-rows[0].value}))};});let chart=lineChart(plotted,start,end,'River level change (metres)');const rain=valid(series.rain.readings).filter(r=>ms(r)>start&&ms(r)<=end&&r.value>=0);const buckets=new Map();rain.forEach(r=>{const k=Math.floor((ms(r)-1)/3600000)*3600000;if(!buckets.has(k))buckets.set(k,[]);buckets.get(k).push(r.value);});const bars=[...buckets].filter(([t,v])=>v.length===4).map(([t,v])=>({t,v:v.reduce((a,b)=>a+b,0)}));const max=Math.max(1,...bars.map(b=>b.v));let rainSvg='<svg viewBox="0 0 940 160" role="img" aria-label="Hourly local rainfall totals in millimetres"><text x="65" y="20" font-size="13" fill="#496a61">Local rainfall (mm / hour)</text>';for(let i=0;i<3;i++){const v=max*i/2,yy=125-v/max*85;rainSvg+=`<path d="M65 ${yy}H915" stroke="#e0e6dc"/><text x="55" y="${yy+4}" text-anchor="end" font-size="12" fill="#5b706b">${v.toFixed(1)}</text>`;}bars.forEach(b=>{const x=65+(b.t-start)/(end-start)*850,w=Math.max(.6,850/((end-start)/3600000)*.8);if(x>=65)rainSvg+=`<rect x="${x}" y="${125-b.v/max*85}" width="${w}" height="${Math.max(.6,b.v/max*85)}" fill="#468ab8"/>`;});rainSvg+='<text x="65" y="150" font-size="12" fill="#5b706b">Same time window as river chart · zero totals shown as a thin mark</text></svg>';E('comparison-chart').innerHTML=rainSvg+chart;const n=plotted.map(s=>s.points.length);E('history-status').textContent=`Snapshot captured ${new Date(history.retrievedAt).toLocaleString('en-GB',{timeZone:'Europe/London'})} UK time. Window: ${date(start)}–${date(end)}. Diglis: ${n[0]} readings; Bewdley: ${n[1]}; rainfall: ${bars.length} complete hours. Saved history does not update with the live Refresh button.`;}
function renderExperiment(){const r=experiment.results.find(v=>v.horizon===Number(E('horizon').value));if(!r){E('scores').textContent='Not enough complete, aligned data for this experiment.';return;}const max=Math.max(...r.metrics.map(m=>m.maeCm),.001);E('scores').innerHTML=r.metrics.map(m=>`<div class="score-row"><span>${m.model}</span><div class="score-track"><div class="score-fill" style="width:${Math.max(1,m.maeCm/max*100)}%"></div></div><strong>${m.maeCm.toFixed(2)} cm</strong></div>`).join('');const baseline=r.metrics[0].maeCm,enhanced=r.metrics[2].maeCm,skill=baseline>0?(1-enhanced/baseline)*100:null;E('experiment-summary').textContent=`${r.trainCount} training examples · ${r.testCount} test examples · test ${date(r.testStart*1000)}–${date(r.testEnd*1000)}. `+(skill===null?'Baseline error is zero; relative improvement is undefined.':`The upstream + rain model had ${Math.abs(skill).toFixed(1)}% ${skill>=0?'lower':'higher'} average error than persistence in this sample.`)+' This does not establish reliable flood prediction.';E('experiment-method').textContent=experiment.method;E('prediction-chart').innerHTML=lineChart([{color:'#27756a',gap:5400000,points:r.trace.map(p=>({t:p.time*1000,v:p.actual}))},{color:'#b87e3d',gap:5400000,points:r.trace.map(p=>({t:p.time*1000,v:p.model}))}],r.trace[0].time*1000,r.trace.at(-1).time*1000,'Held-out Diglis level (metres above station datum)');}
fetch('history.json').then(r=>{if(!r.ok)throw Error();return r.json();}).then(d=>{history=d;renderHistory();E('history-days').onchange=renderHistory;}).catch(()=>E('history-status').textContent='Historical snapshot unavailable. Try reloading the page.');fetch('experiment.json').then(r=>{if(!r.ok)throw Error();return r.json();}).then(d=>{experiment=d;renderExperiment();E('horizon').onchange=renderExperiment;}).catch(()=>E('scores').textContent='Experiment results unavailable.');})();
